script:
// Kocsi billentyűzettel – Newton II. törvénye: F_motor − F_ellenállás = m · a
// Cart driven from the keyboard – Newton's second law: F_motor − F_resist = m · a
//   ← → hajtás / drive · Szóköz (nyomva) fék / Space (held) brake · M jelölő / marker · W / S motorerő / motor force
//   Telefonon ugyanezek gombként jelennek meg a vásznon / on a phone the same keys appear as buttons on the canvas

// Vászon: szélesség, magasság (px), háttérszín / Canvas: width, height (px), background colour
stage(1000, 600, "#f6f8fb");
// Felirat a vászon bal felső sarkában / Caption in the top-left corner
title({hu: "Kocsi nyilakkal", en: "Cart with the arrow keys"});
// A grafikon időablaka másodpercben / Chart time window in seconds
plotWindow(15);

// Csúszkák; {keys: "w s"} = az első billentyű növeli, a második csökkenti (nyomva tartva folyamatosan, Shift = 10×)
// Sliders; {keys: "w s"} = the first key raises, the second lowers the value (smoothly while held, Shift = 10×)
param("F", {hu: "Motor húzóereje F", en: "Motor force F"}, 0, 3000, 1200, 50, "N", {keys: "w s"});
param("m", {hu: "Tömeg m", en: "Mass m"}, 200, 2000, 800, 10, "kg", {keys: "e d"});
param("mu", {hu: "Gördülési ellenállás μ", en: "Rolling resistance μ"}, 0, 0.1, 0.015, 0.001, "");
// Kapcsoló {key: "l"} = az L billentyű ki-be kapcsolja / Switch {key: "l"} = the L key turns it on and off
toggle("air", {hu: "Légellenállás", en: "Air drag"}, true, {key: "l"});
// Gomb {key: "Enter"} = az Enter megnyomja / Button {key: "Enter"} = Enter presses it
button({hu: "Vissza a startra", en: "Back to the start"}, reset, {key: "Enter"});

const g = 9.81, rho = 1.2, cA = 0.7;      // nehézségi gyorsulás, levegő sűrűsége, cw·A [m²] / gravity, air density, cd·A [m²]
const SC = 40;                            // lépték: px / m / scale: px per metre
let x = 0, v = 0, a = 0, Fm = 0, Fres = 0, brake = false;
let marker = null;                        // utolsó jelölő helye [m] / position of the last marker [m]

// onKey: lenyomásonként egyszer fut; {label} = felirat az érintőgombon, {help} = leírás a billentyűlistában (⌨ gomb, ?)
// onKey: runs once per press; {label} = text on the touch button, {help} = text in the key list (⌨ button, ?)
onKey("m", () => { marker = x; }, {label: {hu: "Jelölő", en: "Marker"},
  help: {hu: "jelölő a mostani helyre (távolságméréshez)", en: "marker at the current position (to measure distance)"}});

// Leírások a billentyűlistához / texts for the key list
const H_FWD = {help: {hu: "hajtás előre", en: "drive forward"}}, H_BACK = {help: {hu: "hajtás hátra", en: "drive backwards"}};
const H_BRAKE = {label: {hu: "Fék", en: "Brake"}, help: {hu: "fék (nyomva tartva)", en: "brake (hold)"}};

update(dt => {
  // key(): igaz, amíg a billentyű le van nyomva / true while the key is held
  Fm = 0;
  if (key("ArrowRight", H_FWD)) Fm += P.F;
  if (key("ArrowLeft", H_BACK)) Fm -= P.F;
  brake = key(" ", H_BRAKE);
  // Ellenállások: gördülés, fék, levegő – mindig a mozgással szemben / resistances: rolling, brake, air – always against the motion
  const Fstat = P.mu * P.m * g + (brake ? 0.7 * P.m * g : 0);
  const Fair = P.air ? 0.5 * rho * cA * v * abs(v) : 0;
  if (abs(v) < 1e-3 && abs(Fm) <= Fstat) { v = 0; a = 0; Fres = Fm; return; }   // áll, és az erő nem elég / at rest, the force is not enough
  Fres = (abs(v) < 1e-3 ? sign(Fm) : sign(v)) * Fstat + Fair;
  a = (Fm - Fres) / P.m;
  const v0 = v;
  v += a * dt;
  // a fék és a súrlódás megállít, de nem fordít vissza / brakes and friction stop the cart but never reverse it
  if (v0 !== 0 && sign(v) !== sign(v0) && Fm * v0 <= 0) { v = 0; a = 0; }
  x += v * dt;
});

draw(t => {
  const cam = x - 6;                      // a kamera követi a kocsit / the camera follows the cart
  const X = m => 120 + (m - cam) * SC;    // méter → képpont / metres → pixels
  const Y0 = 430;                         // az út szintje / road level
  ground(Y0);
  // Távolságjelek 1 m-enként, felirat 5 m-enként / distance ticks every metre, labelled every 5 m
  for (let m = Math.floor(cam - 4); m < cam + 24; m++) {
    const px = X(m);
    line(px, Y0, px, Y0 + (m % 5 === 0 ? 16 : 7), {stroke: C.gray, lw: m % 5 === 0 ? 2 : 1});
    if (m % 5 === 0) text(m + " m", px, Y0 + 34, {size: 13, color: C.gray, align: "center"});
  }
  // Jelölő és a tőle mért távolság / marker and the distance from it
  if (marker !== null) {
    line(X(marker), 250, X(marker), Y0, {stroke: C.purple, lw: 2, dash: [6, 5]});
    text("M", X(marker), 240, {size: 15, bold: true, color: C.purple, align: "center"});
  }

  // A kocsi / the cart
  const cx = X(x), r = 22, ang = x / (r / SC);
  rect(cx - 70, Y0 - 2 * r - 58, 140, 58, {fill: C.blue, stroke: "#173b8f", lw: 2, radius: 8});
  rect(cx - 40, Y0 - 2 * r - 82, 74, 26, {fill: "#9fb7e8", stroke: "#173b8f", lw: 2, radius: 6});
  for (const wx0 of [cx - 42, cx + 42]) {
    circle(wx0, Y0 - r, r, {fill: "#2b3240"});
    line(wx0, Y0 - r, wx0 + 0.8 * r * cos(ang), Y0 - r + 0.8 * r * sin(ang), {stroke: "#cfd6e2", lw: 3});
  }
  if (brake) text({hu: "FÉK", en: "BRAKE"}, cx, Y0 - 2 * r - 22, {size: 16, bold: true, color: "#fff", align: "center"});

  // Erővektorok: 1000 N = 60 px / force vectors: 1000 N = 60 px
  const k = 60 / 1000, yF = Y0 - 2 * r - 110;
  if (abs(Fm) > 20) vector(cx, yF, Fm * k, 0, {stroke: C.green, lw: 4}, "F");
  if (abs(Fres) > 20) vector(cx, yF + 18, -Fres * k, 0, {stroke: C.red, lw: 4}, {hu: "F ell.", en: "F res."});
  const Fnet = P.m * a;
  if (abs(Fnet) > 20) vector(cx, yF - 22, Fnet * k, 0, {stroke: C.ink, lw: 2, dash: [6, 4]}, "m·a");

  // Útmutató / hint
  text({hu: "← → hajtás   ·   Szóköz: fék   ·   M: jelölő   ·   W / S: motorerő   ·   P: szünet",
        en: "← → drive   ·   Space: brake   ·   M: marker   ·   W / S: motor force   ·   P: pause"}, 500, 560, {size: 15, color: C.gray, align: "center"});

  // Mért értékek és grafikonok / readouts and charts
  show({hu: "Sebesség v", en: "Speed v"}, v * 3.6, "km/h", 1);
  show({hu: "Gyorsulás a", en: "Acceleration a"}, a, "m/s²");
  show({hu: "Motor ereje", en: "Motor force"}, Fm, "N", 0);
  show({hu: "Ellenállás", en: "Resistance"}, Fres, "N", 0);
  show({hu: "Helyzet x", en: "Position x"}, x, "m", 1);
  if (marker !== null) show({hu: "Távolság a jelölőtől", en: "Distance from the marker"}, x - marker, "m", 1);
  plot({hu: "Sebesség v", en: "Speed v"}, v * 3.6, {unit: "km/h", color: C.blue});
  plot({hu: "Motor ereje", en: "Motor force"}, Fm, {unit: "N", color: C.green, group: "F"});
  plot({hu: "Ellenállás", en: "Resistance"}, Fres, {unit: "N", color: C.red, group: "F"});
});
